import{o as h,c,ak as i}from"./chunks/framework.3a0Z_LB9.js";const a=JSON.parse('{"title":"Điều chỉnh công cụ dụng cụ","description":"","frontmatter":{"prev":{"text":"Phân bổ chi phí CCDC","link":"/TT99/phan-bo-chi-phi-ccdc"},"next":{"text":"Kiểm kê công cụ dụng cụ","link":"/TT99/kiem-ke-cong-cu-dung-cu"}},"headers":[],"relativePath":"TT99/dieu-chinh-cong-cu-dung-cu.md","filePath":"TT99/dieu-chinh-cong-cu-dung-cu.md"}'),t={name:"TT99/dieu-chinh-cong-cu-dung-cu.md"},e=Object.assign(t,{setup(g){return(p,n)=>(h(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="đieu-chinh-cong-cu-dung-cu" tabindex="-1">Điều chỉnh công cụ dụng cụ <a class="header-anchor" href="#đieu-chinh-cong-cu-dung-cu" aria-label="Permalink to “Điều chỉnh công cụ dụng cụ”">​</a></h1><p>Đường dẫn có dạng <a href="https://a.bkit.vn/dieu-chinh-ccdc" target="_blank" rel="noreferrer">https://a.bkit.vn/dieu-chinh-ccdc</a></p><p>Tổng quan Mục đích: Bài viết hướng dẫn quy định và thao tác điều chỉnh giá trị công cụ dụng cụ (CCDC), điều chỉnh giảm, điều chỉnh giảm một phần, điều chỉnh tăng, điều chỉnh tăng một phần giá trị CCDC trên phần mềm khi phát sinh nghiệp vụ sửa chữa hoặc tháo dỡ.</p><p>Nội dung:</p><p>Quy định điều chỉnh giá trị và thời gian sử dụng CCDC sau sửa chữa, tháo dỡ Hướng dẫn chi tiết thao tác điều chỉnh giá trị CCDC trên phần mềm Phạm vi áp dụng: Kế toán, cán bộ quản lý tài sản, nhân viên phụ trách công cụ dụng cụ</p><p>Ví dụ: Ngày 14 tháng 03 năm 2026, công ty TNHH BKIT Việt Nam nâng cấp thêm một ổ cứng 512 GB cho mỗi máy tính của 3 trưởng phòng:</p><ul><li>Trưởng phòng Kinh doanh</li><li>Trưởng phòng Hành chính</li><li>Trưởng phòng Kế toán. Đơn giá mỗi ổ cứng là 980.000 đồng, đã thanh toán bằng tiền mặt.</li></ul><p><strong>Lập phiếu chi tiền mặt.</strong> Các bước thực hiện: Hạch toán tăng/Giảm chi phí chờ phân bổ: Tùy thuộc vào hình thức thanh toán mà việc hạch toán được thực hiện như sau (Ví dụ trường hợp tăng):</p><p>Trường hợp chi tiền mặt</p><ul><li><p>Vào phân hệ Qũy\\ chọn Thu, chi tiền\\ thêm Chi tiền</p></li><li><p>Khai báo thông tin phiếu chi: Đối tượng, Địa chỉ, Lý do chi,… và Hạch toán:</p></li><li><p>Nợ TK 242/Có TK 111 : Số tiền chi ra</p></li><li><p>Điều chỉnh công cụ dụng cụ theo Chứng từ Phiếu chi tiền mặt ở phía trên.</p></li></ul><p>Lưu ý: Trước khi điều chỉnh CCDC, thì có thể là Lập ủy nhiệm chi ngân hàng.</p>',11)])]))}});export{a as __pageData,e as default};
